mapper.select:
SELECT s.id AS studentId, s.student_no AS studentNo, s.name AS studentName, COUNT(sc.id) AS courseCount, ROUND(AVG(sc.total_score), 1) AS avgScore, MAX(sc.total_score) AS maxScore, MIN(sc.total_score) AS minScore, ROUND(SUM(sc.total_score), 1) AS sumScore, SUM(CASE WHEN sc.total_score >= 60 THEN 1 ELSE 0 END) AS passCount FROM student s LEFT JOIN score sc ON sc.student_id = s.id AND sc.course_id = #{courseId} AND sc.semester = #{semester}
AND s.class_id = #{classId}
GROUP BY s.id, s.student_no, s.name ORDER BY avgScore DESC

SELECT c.id AS courseId, c.course_name AS courseName, t.name AS teacherName, COUNT(sc.id) AS studentCount, ROUND(AVG(sc.total_score), 1) AS avgScore, MAX(sc.total_score) AS maxScore, MIN(sc.total_score) AS minScore, ROUND(SUM(CASE WHEN sc.total_score >= 60 THEN 1 ELSE 0 END) * 100 / NULLIF(COUNT(sc.id), 0), 1) AS passRate, ROUND(SUM(CASE WHEN sc.total_score >= 90 THEN 1 ELSE 0 END) * 100 / NULLIF(COUNT(sc.id), 0), 1) AS excellentRate FROM score sc JOIN student s ON sc.student_id = s.id JOIN course c ON sc.course_id = c.id LEFT JOIN teacher t ON c.teacher_id = t.id
AND s.class_id = #{classId} AND sc.semester = #{semester}
GROUP BY c.id, c.course_name, t.name ORDER BY c.id ASC

SELECT CASE WHEN sc.total_score >= 90 THEN '优秀(90-100)' WHEN sc.total_score >= 80 THEN '良好(80-89)' WHEN sc.total_score >= 70 THEN '中等(70-79)' WHEN sc.total_score >= 60 THEN '及格(60-69)' ELSE '不及格(0-59)' END AS segment, COUNT(*) AS cnt FROM score sc JOIN student s ON sc.student_id = s.id
sc.total_score IS NOT NULL AND s.class_id = #{classId} AND sc.course_id = #{courseId} AND sc.semester = #{semester}
GROUP BY segment ORDER BY MIN(sc.total_score) ASC
